#include "parksmart.h"
#include <stdlib.h>
#include <string.h>
#include <limits.h>
static void merge(int*a,int*t,int l,int r){if(r-l<2)return;int m=(l+r)/2;merge(a,t,l,m);merge(a,t,m,r);int i=l,j=m;for(int k=l;k<r;k++)t[k]=j==r||(i<m&&a[i]<=a[j])?a[i++]:a[j++];for(int k=l;k<r;k++)a[k]=t[k];}
void merge_sort(int*a,int n){if(n<=0)return;int*t=malloc((size_t)n*sizeof(int));if(t){merge(a,t,0,n);free(t);}}
static void quick(int*a,int l,int r){while(l<r){int pivot=a[(l+r)/2],i=l,j=r;while(i<=j){while(a[i]<pivot)i++;while(a[j]>pivot)j--;if(i<=j){int t=a[i];a[i++]=a[j];a[j--]=t;}}if(j-l<r-i){if(l<j)quick(a,l,j);l=i;}else{if(i<r)quick(a,i,r);r=j;}}}
void quick_sort(int*a,int n){if(n>1)quick(a,0,n-1);}
int binary_search_iter(const int*a,int n,int x){int l=0,r=n-1;while(l<=r){int m=l+(r-l)/2;if(a[m]==x)return m;if(a[m]<x)l=m+1;else r=m-1;}return -1;}
int binary_search_rec(const int*a,int l,int r,int x){if(l>r)return -1;int m=l+(r-l)/2;return a[m]==x?m:(a[m]<x?binary_search_rec(a,m+1,r,x):binary_search_rec(a,l,m-1,x));}
int naive_search(const char*t,const char*p){int n=(int)strlen(t),m=(int)strlen(p);for(int i=0;i+m<=n;i++)if(!strncmp(t+i,p,(size_t)m))return i;return -1;}
int kmp_search(const char*t,const char*p){int n=(int)strlen(t),m=(int)strlen(p);if(!m)return 0;int*l=calloc((size_t)m,sizeof(int));if(!l)return -1;for(int i=1,j=0;i<m;){if(p[i]==p[j])l[i++]=++j;else if(j)j=l[j-1];else l[i++]=0;}int found=-1;for(int i=0,j=0;i<n;){if(t[i]==p[j]){i++;j++;if(j==m){found=i-m;break;}}else if(j)j=l[j-1];else i++;}free(l);return found;}
int rabin_karp_search(const char*t,const char*p){int n=(int)strlen(t),m=(int)strlen(p);if(!m)return 0;if(m>n)return -1;long long h=1,pt=0,tt=0;for(int i=1;i<m;i++)h=h*256%1000000007;for(int i=0;i<m;i++){pt=(pt*256+(unsigned char)p[i])%1000000007;tt=(tt*256+(unsigned char)t[i])%1000000007;}for(int i=0;i<=n-m;i++){if(pt==tt&&!strncmp(t+i,p,(size_t)m))return i;if(i<n-m){tt=(tt-(unsigned char)t[i]*h%1000000007+1000000007)%1000000007;tt=(tt*256+(unsigned char)t[i+m])%1000000007;}}return -1;}
int max_subarray(const int*a,int n){if(n<=0)return 0;int best=a[0],cur=a[0];for(int i=1;i<n;i++){cur=cur>0?cur+a[i]:a[i];if(cur>best)best=cur;}return best;}
long long fast_power(long long a,unsigned int b){long long r=1;while(b){if(b&1)r*=a;a*=a;b>>=1;}return r;}
int knapsack(const int*w,const int*v,int n,int c){if(c<0)return -1;int*dp=calloc((size_t)c+1,sizeof(int));if(!dp)return -1;for(int i=0;i<n;i++)if(w[i]>0)for(int j=c;j>=w[i];j--)if(dp[j-w[i]]+v[i]>dp[j])dp[j]=dp[j-w[i]]+v[i];int result=dp[c];free(dp);return result;}
int lcs_length(const char*a,const char*b){int n=(int)strlen(a),m=(int)strlen(b);int*dp=calloc((size_t)m+1,sizeof(int));if(!dp)return -1;for(int i=1;i<=n;i++){int prev=0;for(int j=1;j<=m;j++){int tmp=dp[j];if(a[i-1]==b[j-1])dp[j]=prev+1;else if(dp[j-1]>dp[j])dp[j]=dp[j-1];prev=tmp;}}int x=dp[m];free(dp);return x;}
static int queens(int n,int row,unsigned int col,unsigned int a,unsigned int b){if(row==n)return 1;int count=0;unsigned int allowed=((1u<<n)-1)&~(col|a|b);while(allowed){unsigned int bit=allowed&-allowed;allowed-=bit;count+=queens(n,row+1,col|bit,(a|bit)<<1,(b|bit)>>1);}return count;}
int nqueens_count(int n){return n>=1&&n<=12?queens(n,0,0,0,0):0;}
int subset_sum(const int*a,int n,int target){if(target==0)return 1;if(n==0)return 0;return subset_sum(a+1,n-1,target)||subset_sum(a+1,n-1,target-a[0]);}
static int egcd(int a,int b,int*x,int*y){if(!b){*x=1;*y=0;return a;}int x1,y1,g=egcd(b,a%b,&x1,&y1);*x=y1;*y=x1-(a/b)*y1;return g;}
int crt_pair(int a,int m,int b,int n){if(m<=0||n<=0)return -1;int x,y,g=egcd(m,n,&x,&y);if((b-a)%g)return -1;long long mod=(long long)m/g*n;if(mod>INT_MAX)return -1;long long k=((long long)(b-a)/g*x)%(n/g);long long res=((long long)a+(long long)m*k)%mod;return (int)(res<0?res+mod:res);}
int prim_mst(const System*s){int seen[MAX_NODES]={0},d[MAX_NODES];for(int i=0;i<s->nodes;i++)d[i]=INF;d[0]=0;int sum=0;for(int k=0;k<s->nodes;k++){int u=-1;for(int i=0;i<s->nodes;i++)if(!seen[i]&&(u<0||d[i]<d[u]))u=i;if(u<0||d[u]==INF)return -1;seen[u]=1;sum+=d[u];for(int v=0;v<s->nodes;v++)if(!seen[v]&&s->graph[u][v]<d[v])d[v]=s->graph[u][v];}return sum;}
static int root(int*p,int x){while(p[x]!=x){p[x]=p[p[x]];x=p[x];}return x;}
int kruskal_mst(const System*s){int p[MAX_NODES];for(int i=0;i<s->nodes;i++)p[i]=i;int sum=0,count=0;while(count<s->nodes-1){int best=INF,u=-1,v=-1;for(int i=0;i<s->nodes;i++)for(int j=i+1;j<s->nodes;j++)if(root(p,i)!=root(p,j)&&s->graph[i][j]<best){best=s->graph[i][j];u=i;v=j;}if(u<0)return -1;p[root(p,u)]=root(p,v);sum+=best;count++;}return sum;}
int bellman_ford(const System*s,int source,int*d){if(source<0||source>=s->nodes)return 0;for(int i=0;i<s->nodes;i++)d[i]=INF;d[source]=0;for(int k=1;k<s->nodes;k++)for(int i=0;i<s->nodes;i++)for(int j=0;j<s->nodes;j++)if(d[i]<INF&&s->graph[i][j]<INF&&d[i]+s->graph[i][j]<d[j])d[j]=d[i]+s->graph[i][j];return 1;}
void floyd_warshall(const System*s,int d[MAX_NODES][MAX_NODES]){memcpy(d,s->graph,sizeof(s->graph));for(int k=0;k<s->nodes;k++)for(int i=0;i<s->nodes;i++)for(int j=0;j<s->nodes;j++)if(d[i][k]<INF&&d[k][j]<INF&&d[i][k]+d[k][j]<d[i][j])d[i][j]=d[i][k]+d[k][j];}
static void tsp_dfs(int d[10][10],int n,int u,int mask,int cost,int*best){if(cost>=*best)return;if(mask==(1<<n)-1){if(d[u][0]<INF&&cost+d[u][0]<*best)*best=cost+d[u][0];return;}for(int v=1;v<n;v++)if(!(mask&(1<<v))&&d[u][v]<INF)tsp_dfs(d,n,v,mask|(1<<v),cost+d[u][v],best);}
int tsp_exact(const System*s,int*nodes,int n){if(n<2||n>10)return -1;int all[MAX_NODES][MAX_NODES];floyd_warshall(s,all);int d[10][10];for(int i=0;i<n;i++)for(int j=0;j<n;j++){if(nodes[i]<0||nodes[i]>=s->nodes||nodes[j]<0||nodes[j]>=s->nodes)return -1;d[i][j]=all[nodes[i]][nodes[j]];}int best=INF;tsp_dfs(d,n,0,1,0,&best);return best==INF?-1:best;}
static int augment(int u,int cols,const int e[32][32],int*seen,int*match){for(int v=0;v<cols;v++)if(e[u][v]&&!seen[v]){seen[v]=1;if(match[v]<0||augment(match[v],cols,e,seen,match)){match[v]=u;return 1;}}return 0;}
int max_bipartite_matching(int rows,int cols,const int e[32][32]){if(rows<0||rows>32||cols<0||cols>32)return -1;int match[32],count=0;for(int i=0;i<32;i++)match[i]=-1;for(int u=0;u<rows;u++){int seen[32]={0};count+=augment(u,cols,e,seen,match);}return count;}
int ford_fulkerson(int n,int cap[32][32],int source,int sink){if(n<2||n>32||source<0||sink<0||source>=n||sink>=n||source==sink)return -1;int r[32][32];memcpy(r,cap,sizeof(r));int flow=0;for(;;){int p[32],q[32],h=0,t=0;for(int i=0;i<n;i++)p[i]=-1;p[source]=source;q[t++]=source;while(h<t&&p[sink]<0){int u=q[h++];for(int v=0;v<n;v++)if(p[v]<0&&r[u][v]>0){p[v]=u;q[t++]=v;}}if(p[sink]<0)break;int f=INF;for(int v=sink;v!=source;v=p[v])if(r[p[v]][v]<f)f=r[p[v]][v];for(int v=sink;v!=source;v=p[v]){r[p[v]][v]-=f;r[v][p[v]]+=f;}flow+=f;}return flow;}
